const verified = $json.users?.[0] ?? {};
const userId = verified.localId;
if (!userId) {
  throw new Error('Firebase token did not resolve to a user.');
}
if (verified.disabled === true) {
  throw new Error('This Firebase account is disabled.');
}

const body = $('Offer IQ Webhook').first().json.body ?? {};
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const sessionId = UUID_RE.test(String(body.session_id ?? '')) ? String(body.session_id) : crypto.randomUUID();

return [{
  json: {
    session_id: sessionId,
    user_id: userId,
    focus: body.focus || 'High-converting client acquisition offer',
    delivery: body.delivery || 'Done-With-You / Agency',
    paid_traffic: body.paid_traffic || 'Organic & Paid Traffic',
    timeline: body.timeline || '6-12 weeks',
    pricing: body.pricing || '$3,000 - $10,000',
    blueprint: body.blueprint && typeof body.blueprint === 'object' ? body.blueprint : null,
    asset_context: String(body.asset_context ?? ''),
    selected_sections: Array.isArray(body.selected_sections) ? body.selected_sections : []
  }
}];

