function toList(value) {
  if (Array.isArray(value)) {
    return value.map((item) => String(item ?? '').trim()).filter(Boolean);
  }
  if (typeof value === 'string') {
    return value.split(/\r?\n|[;•]|,(?=\s)/).map((part) => part.trim()).filter(Boolean);
  }
  return [];
}

const source = $input.first().json;
const raw = source.output ?? source.text ?? source.response?.text ?? source;
let offer = raw;
if (typeof raw === 'string') {
  try {
    offer = JSON.parse(raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
  } catch {
    throw new Error('Offer IQ agent did not return valid JSON.');
  }
}
if (offer?.output) offer = offer.output;
if (!offer || typeof offer !== 'object' || !offer.title) {
  throw new Error('Offer IQ agent returned an incomplete offer.');
}

// The app renders these as string arrays; the model sometimes returns prose.
offer.scope = toList(offer.scope);
offer.success_metrics = toList(offer.success_metrics);

const input = $('Merge Saved Context').first().json;
const now = new Date().toISOString();
offer.generated_at = now;

const buyer = input.buyer && Object.keys(input.buyer).length ? input.buyer : { persona_name: offer.audience };

return [{
  json: {
    ...offer,
    offer,
    session_id: input.session_id,
    user_id: input.user_id,
    blueprint: { ...buyer, offer }
  }
}];

const headers = $json.headers ?? {};
const raw = headers.authorization ?? headers.Authorization ?? '';
const token = String(raw).replace(/^Bearer\s+/i, '').trim();
if (!token || token.length > 8192) {
  throw new Error('Missing Firebase ID token in the Authorization header.');
}
return [{ json: { id_token: token } }];

const input = $('Verify User and Normalize').first().json;
const ownedBy = (doc) => (doc && (!doc.owner_id || doc.owner_id === input.user_id) ? doc : {});

const memory = ownedBy($('Load Account Memory').first()?.json);
const session = ownedBy($input.first()?.json);

// Per-user prompt layers written in the background by the profile builder.
// Used as DATA only — never as instructions.
const layers = memory.prompt_layers && typeof memory.prompt_layers === 'object' ? memory.prompt_layers : {};

const buyer = session.blueprint
  ?? memory.audience_profile
  ?? input.blueprint
  ?? {};

return [{
  json: {
    ...input,
    buyer,
    offer_guidance: String(layers.offer_guidance ?? '').slice(0, 2000),
    business_profile: memory.business_profile ?? {},
    offer_profile: memory.offer_profile ?? {},
    brand_profile: memory.brand_profile ?? {},
    memory_summary: memory.memory_summary ?? ''
  }
}];

const result = $input.first().json;
const now = new Date().toISOString();

return [{
  json: {
    session_id: result.session_id,
    owner_id: result.user_id,
    status: 'completed',
    step: 4,
    blueprint: result.blueprint,
    onboarding_complete: true,
    audience_profile: result.blueprint,
    offer_profile: result.offer,
    source_session_id: result.session_id,
    updated_at: now
  }
}];

// Reached when the agent or the validator fails. Return the offer the user
// already had rather than failing the request outright.
let input = {};
try {
  input = $('Merge Saved Context').first().json ?? {};
} catch {
  try { input = $('Verify User and Normalize').first().json ?? {}; } catch { input = {}; }
}

const failure = $input.first()?.json ?? {};
console.log('Webinar Offer recovered from a failed turn:', String(failure.error?.message ?? failure.message ?? '').slice(0, 300));

const previousOffer = input.offer_profile && Object.keys(input.offer_profile).length ? input.offer_profile : null;

return [{
  json: {
    ...(previousOffer ?? {}),
    offer: previousOffer,
    error: "That offer didn't generate cleanly. Nothing was overwritten — try again, or adjust the inputs first.",
    recovered: true,
    session_id: input.session_id ?? null,
    user_id: input.user_id ?? null,
    blueprint: input.buyer ?? {}
  }
}];
